mapper.update:
UPDATE `inspection`.inspection_receipt a
SET
SHEET_ID=#{params.SHEET_ID}
,TASK_TYPE_DSCR=#{params.TASK_TYPE_DSCR}
,TASK_ID=#{params.TASK_ID}
,FILLING_DATE=#{params.FILLING_DATE}
,AGENT_SUBJECT=#{params.AGENT_SUBJECT}
,PHYSICAL_NUM=#{params.PHYSICAL_NUM}
,BALANCE=#{params.BALANCE}
,REASON=#{params.REASON}
,OPERATOR=#{params.OPERATOR}
,CUSTODIAN=#{params.CUSTODIAN}
,LARDER=#{params.LARDER}
,RUMMAGER=#{params.RUMMAGER}
,ATTACHMENT_NAME=#{params.ATTACHMENT_NAME}
,PAPER_ATTACHMENT=#{params.PAPER_ATTACHMENT}
,PRINT_ATTACHMENT=#{params.PRINT_ATTACHMENT}
,INSPECTED=#{params.INSPECTED}
,ADD_USERID=#{params.ADD_USERID}
,ADD_DATE=#{params.ADD_DATE}
,MODIFY_USERID=#{params.MODIFY_USERID}
,MODIFY_DATE=#{params.MODIFY_DATE}
WHERE 1=1

    AND a.`TASK_ID` = #{params.TASK_ID}


    AND a.`SHEET_ID` = #{params.SHEET_ID}

mapper.select:
SELECT a.* ,c.name AS NAME, CONCAT(d.`guoku_dscr`,'国家债券收款单现场检查账实核对表') AS SHEET_NAME, d.`guoku_dscr` as INSPECTED_DSCR FROM `inspection`.`inspection_receipt` a LEFT JOIN dmcode.`cm_guoku_dimnsn` d ON a.INSPECTED=d.`guoku_id` LEFT JOIN inspection.inspection_sysuser_talentpool_relation b ON b.SYS_USERID = a.ADD_USERID LEFT JOIN inspection.cm_guoku_talentpool c ON b.TALENTPOOL_ID = c.UUID where 1=1
AND a.TASK_ID = #{params.TASK_ID}
order by ADD_DATE,a.MODIFY_DATE desc

mapper.delete:
delete from `inspection`.`inspection_receipt` where 1=1

    AND TASK_ID = #{params.TASK_ID}


    AND INSPECTED = #{params.INSPECTED}

mapper.select:
SELECT * FROM    `inspection`.`inspection_receipt` a
 WHERE 1=1

      AND TASK_ID = #{params.TASK_ID}


      AND INSPECTED = #{params.INSPECTED}

mapper.update:
 update   inspection.inspection_process_sub set
 INSPECTION_PROCESS_SUB_SIGN =0
, FINISH_TIME=#{params.FINISH_TIME}
 where   ID = #{params.ID}
